import React from 'react';
import s from './PlanCards.module.css';

// The middle tier is visually featured — a common, low-risk pricing-page
// convention — but every plan is otherwise presented identically since they
// only differ by price right now (no feature gating between tiers yet).
const FEATURED_PLAN_ID = 'growth';

export function PlanCards({ plans, billingCycleDays, selectedPlanId, currentPlanId, onSelect, disabled }) {
  if (!plans || plans.length === 0) return null;

  return (
    <div className={s.grid}>
      {plans.map(plan => {
        const isSelected = selectedPlanId === plan.plan_id;
        const isCurrent = currentPlanId === plan.plan_id;
        const isFeatured = plan.plan_id === FEATURED_PLAN_ID;

        return (
          <button
            key={plan.plan_id}
            type="button"
            disabled={disabled}
            className={`${s.card} ${isSelected ? s.cardSelected : ''} ${isFeatured ? s.cardFeatured : ''}`}
            onClick={() => onSelect?.(plan.plan_id)}
          >
            {isFeatured && !isCurrent && <span className={s.badge}>Most popular</span>}
            {isSelected && <span className={s.checkmark}>✓</span>}

            <span className={s.planName}>{plan.name}</span>
            <span className={s.priceRow}>
              <span className={s.priceAmount}>{plan.currency === 'USD' ? '$' : `${plan.currency} `}{Math.round(parseFloat(plan.amount))}</span>
              <span className={s.priceCurrency}>{plan.currency}</span>
              <span className={s.pricePeriod}>/ {billingCycleDays ? `${billingCycleDays} days` : 'month'}</span>
            </span>
            <span className={s.planDesc}>{plan.description}</span>
            {isCurrent && <span className={s.currentBadge}>✓ Current plan</span>}
          </button>
        );
      })}
    </div>
  );
}
